import{_ as a,a as s,c as t,ac as o}from"./chunks/framework.BSuaGltH.js";const m=JSON.parse('{"title":"第四册：流利英语 · 单元 3 复习与自测","description":"L17–L24 原创练习和答案解析。","frontmatter":{"title":"第四册：流利英语 · 单元 3 复习与自测","description":"L17–L24 原创练习和答案解析。","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"读写与对话练习","scope":"general","audience":"general","group":"学习与记录","summary":"L17–L24 原创练习和答案解析。","status":"active","related":[{"title":"程序员英语 01：学习路线与能力自测","link":"/life/english/programmer/overview","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 02：技术词汇与句子骨架","link":"/life/english/programmer/vocabulary","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 03：读懂文档中的条件与约束","link":"/life/english/programmer/reading-docs","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 04：读报错、搜索与求助","link":"/life/english/programmer/errors-search","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 05：写 Issue、Commit 与 PR","link":"/life/english/programmer/issue-pr","kind":"路线与能力起点","scope":"general","audience":"general"}],"prev":{"text":"第四册：流利英语 · 单元 3 单词与短语","link":"/life/english/new-concept/book-4/unit-03/vocabulary"},"next":{"text":"第四册：流利英语 · 单元 4：机制、反事实与专业沟通","link":"/life/english/new-concept/book-4/unit-04/overview"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"第四册：流利英语 · 单元 3 单词与短语","link":"/life/english/new-concept/book-4/unit-03/vocabulary"},"next":{"text":"第四册：流利英语 · 单元 4：机制、反事实与专业沟通","link":"/life/english/new-concept/book-4/unit-04/overview"}},"headers":[],"relativePath":"life/english/new-concept/book-4/unit-03/review.md","filePath":"life/english/new-concept/book-4/unit-03/review.md"}'),n={name:"life/english/new-concept/book-4/unit-03/review.md"};function r(i,e,l,p,c,h){return s(),t("div",null,[...e[0]||(e[0]=[o('<h1 id="第四册-流利英语-·-单元-3-复习与自测" tabindex="-1">第四册：流利英语 · 单元 3 复习与自测 <a class="header-anchor" href="#第四册-流利英语-·-单元-3-复习与自测" aria-label="Permalink to &quot;第四册：流利英语 · 单元 3 复习与自测&quot;">​</a></h1><p><a href="/life/english/new-concept/book-4/unit-03/overview">单元导读</a> · <a href="/life/english/new-concept/book-4/unit-03/grammar">单元语法总结</a> · <a href="/life/english/new-concept/book-4/unit-03/vocabulary">单元单词与短语</a> · <a href="/life/english/new-concept/book-4/unit-03/review">单元复习与自测</a></p><p>先独立作答，再展开答案。下列原创题从相应课时选取，覆盖本范围每一课；错题请回到课时讲解解释错误原因，再替换一个条件重做。</p><h2 id="lesson-17-·-cause、lead-to-与-be-associated-with" tabindex="-1">Lesson 17 · cause、lead to 与 be associated with <a class="header-anchor" href="#lesson-17-·-cause、lead-to-与-be-associated-with" aria-label="Permalink to &quot;Lesson 17 · cause、lead to 与 be associated with&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> In the fictional survey, a wetter spring was associated with fewer rabbits near the field.</p><h3 id="练习-1" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1" aria-label="Permalink to &quot;练习 1&quot;">​</a></h3><p>示例是否已经证明更潮湿的春季导致兔子减少？</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> 没有。</p><p><strong>解析：</strong> be associated with 表关联，还需要排除其他解释。</p></details><p><strong>表达迁移：</strong> 为虚构兔子数量调查写三句摘要：一项关联、另一种解释、后续观察需要。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>A wetter spring was associated with fewer rabbits near the field. Changes in food supply may also explain the difference. A better survey would compare several sites over more than one season.</p><p>用关联、替代解释和跨地点观察构成谨慎摘要，不据历史疾病故事提供干预步骤。</p></details><p><a href="/life/english/new-concept/book-4/unit-03/lesson-017">回看本课</a></p><h2 id="lesson-18-·-感官动词的主动与被动转换" tabindex="-1">Lesson 18 · 感官动词的主动与被动转换 <a class="header-anchor" href="#lesson-18-·-感官动词的主动与被动转换" aria-label="Permalink to &quot;Lesson 18 · 感官动词的主动与被动转换&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> The animal was seen to surface beside the boat twice.</p><h3 id="练习-1-1" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-1" aria-label="Permalink to &quot;练习 1&quot;">​</a></h3><p>把 We saw the animal turn. 改成被动句。</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> The animal was seen to turn.</p><p><strong>解析：</strong> 被动结构中的不定式恢复 to。</p></details><p><strong>表达迁移：</strong> 写三句海边观察笔记：一次所见、一个未知问题、一次进一步观察计划。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>A small animal was seen to surface near the harbour. We could not identify its species from that distance. Next time, we will record its shape and movement more carefully.</p><p>描述行为而不编造意图，并把物种识别的不确定性写出来。</p></details><p><a href="/life/english/new-concept/book-4/unit-03/lesson-018">回看本课</a></p><h2 id="lesson-19-·-同位语从句与定语从句" tabindex="-1">Lesson 19 · 同位语从句与定语从句 <a class="header-anchor" href="#lesson-19-·-同位语从句与定语从句" aria-label="Permalink to &quot;Lesson 19 · 同位语从句与定语从句&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> The belief that every dream has one fixed meaning is difficult to justify.</p><h3 id="练习-1-2" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-2" aria-label="Permalink to &quot;练习 1&quot;">​</a></h3><p>示例中的 that 从句说明 belief 的内容还是修饰提出它的人？</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> 说明 belief 的内容。</p><p><strong>解析：</strong> 从句本身结构完整。</p></details><p><strong>表达迁移：</strong> 写三句评价一个梦的解释：陈述回忆、提出可能联系、保留其他解释。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>I remembered a dream about a crowded station. It may have reflected my worries about an upcoming trip. That interpretation is possible, but it is not the only one.</p><p>回忆与解释分句处理，may 和 not the only one 避免把主观推测当成唯一答案。</p></details><p><a href="/life/english/new-concept/book-4/unit-03/lesson-019">回看本课</a></p><h2 id="lesson-20-·-过去分词作后置定语" tabindex="-1">Lesson 20 · 过去分词作后置定语 <a class="header-anchor" href="#lesson-20-·-过去分词作后置定语" aria-label="Permalink to &quot;Lesson 20 · 过去分词作后置定语&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> The samples collected on Tuesday were analysed separately.</p><h3 id="练习-1-3" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-3" aria-label="Permalink to &quot;练习 1&quot;">​</a></h3><p>展开 samples collected on Tuesday 中的分词定语。</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> samples that were collected on Tuesday</p><p><strong>解析：</strong> 过去分词定语对应被动关系从句。</p></details><p><strong>表达迁移：</strong> 用三句写实验样本管理说明，包含采集、分组和结论范围。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>The samples collected at different sites were kept separate. Each group was given a clear label. Results from one group cannot automatically be applied to another.</p><p>用分词定语说明来源，用末句避免跨组过度概括；不涉及危险操作或医疗处置。</p></details><p><a href="/life/english/new-concept/book-4/unit-03/lesson-020">回看本课</a></p><h2 id="lesson-21-·-it-is-was-that-强调句" tabindex="-1">Lesson 21 · It is/was…that 强调句 <a class="header-anchor" href="#lesson-21-·-it-is-was-that-强调句" aria-label="Permalink to &quot;Lesson 21 · It is/was…that 强调句&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> It was the actor’s silence that made the final scene so tense.</p><h3 id="练习-1-4" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-4" aria-label="Permalink to &quot;练习 1&quot;">​</a></h3><p>还原示例为普通陈述句。</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> The actor’s silence made the final scene so tense.</p><p><strong>解析：</strong> 去掉强调框架后主干完整。</p></details><p><strong>表达迁移：</strong> 用三句评论一段自选无声电影片段，说明哪种表演手段影响了你。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>It was the long pause that caught my attention. The actor looked towards the empty doorway without moving. This small gesture created more tension than a dramatic speech would have done.</p><p>强调句提出观察焦点，具体动作提供依据，比较句说明效果。</p></details><p><a href="/life/english/new-concept/book-4/unit-03/lesson-021">回看本课</a></p><h2 id="lesson-22-·-what-从句作主语与表语" tabindex="-1">Lesson 22 · what 从句作主语与表语 <a class="header-anchor" href="#lesson-22-·-what-从句作主语与表语" aria-label="Permalink to &quot;Lesson 22 · what 从句作主语与表语&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> What matters is whether the new tool solves a real problem.</p><h3 id="练习-1-5" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-5" aria-label="Permalink to &quot;练习 1&quot;">​</a></h3><p>示例中主句的系动词是什么？</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> is</p><p><strong>解析：</strong> 前后两个从句由 is 连接。</p></details><p><strong>表达迁移：</strong> 用三句评价一款虚构学习工具，给出一个进步标准和一个验证方法。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>What matters is whether students understand more. Faster completion alone does not prove deeper learning. We could compare how well students explain a new problem after using the tool.</p><p>先定标准，再排除替代指标，最后提出能对应标准的验证方式。</p></details><p><a href="/life/english/new-concept/book-4/unit-03/lesson-022">回看本课</a></p><h2 id="lesson-23-·-现在分词状语与逻辑主语" tabindex="-1">Lesson 23 · 现在分词状语与逻辑主语 <a class="header-anchor" href="#lesson-23-·-现在分词状语与逻辑主语" aria-label="Permalink to &quot;Lesson 23 · 现在分词状语与逻辑主语&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> Gliding above the field, the bird turned towards the hills.</p><h3 id="练习-1-6" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-6" aria-label="Permalink to &quot;练习 1&quot;">​</a></h3><p>示例中谁在 gliding？</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> the bird</p><p><strong>解析：</strong> 分词状语与主句共享主语。</p></details><p><strong>表达迁移：</strong> 用三句记录一次鸟类观察，含分词状语、动作变化和观察限制。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>Circling above the trees, a large bird gradually gained height. It then moved across the valley without flapping. From the ground, I could not identify the species with confidence.</p><p>动作描述具体，最后将物种判断与观察事实分开。</p></details><p><a href="/life/english/new-concept/book-4/unit-03/lesson-023">回看本课</a></p><h2 id="lesson-24-·-否定或限制副词前置倒装" tabindex="-1">Lesson 24 · 否定或限制副词前置倒装 <a class="header-anchor" href="#lesson-24-·-否定或限制副词前置倒装" aria-label="Permalink to &quot;Lesson 24 · 否定或限制副词前置倒装&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> Rarely do two viewers notice exactly the same details in a painting.</p><h3 id="练习-1-7" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-7" aria-label="Permalink to &quot;练习 1&quot;">​</a></h3><p>填空：Rarely ___ she choose bright colours.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> does</p><p><strong>解析：</strong> 主语 she，现时一般时倒装用 does。</p></details><p><strong>表达迁移：</strong> 选择一件普通物品写三句审美评论，包含一个具体特征和一个观点限制。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>Rarely do I notice the shape of an ordinary cup. This one has a narrow base and a softly curved handle. I find the proportions pleasing, although another viewer may prefer a simpler form.</p><p>倒装引入反思，具体特征支撑个人评价，让步句保留不同审美。</p></details><p><a href="/life/english/new-concept/book-4/unit-03/lesson-024">回看本课</a></p>',67)])])}const u=a(n,[["render",r]]);export{m as __pageData,u as default};
